  "UcoreRareMetals": {"founded": 2006, "employees": 170, "revenue_2025": "sin ingresos operativos", "market_cap": "CAD 548,42 millones (≈US$390,3 millones, 15-jul-2026)", "capacity": "~9.600 t/año TREO en pleno build-out de la planta de Louisiana (arranque Machine A objetivo H1-2027); sin producción comercial aún", "geo_risk": "Se posiciona como beneficiario directo de los controles chinos al no requerir equipos de origen chino; calificación DPAS DO-B8 (sep-2025) da prioridad legal en contratos de defensa de EEUU.", "desc": "El DOD de EEUU amplió su contrato a US$22,4M acumulados (jun-2025) vía programa IBAS. Firmó un offtake a 10 años con Critical Metals Corp por hasta 10.000 t/año desde Tanbreez, Groenlandia (ago-2025), y un MOU con Vacuumschmelze/eVAC Magnetics (nov-2025). Canadá aprobó condicionalmente hasta CAD 36,3M (oct-2025) para su planta de Kingston."},
  "Nucor": {"founded": 1940, "employees": 33, "revenue_2025": "~US$32.490M (FY2025, verificado)", "market_cap": "~US$58.600M (verificado jul-2026)", "capacity": "~27 millones t/año de acero crudo (múltiples minimills EE.UU.)", "geo_risk": "Beneficiario neto de Sección 232, pero el modelo EAF depende de electricidad barata/estable y precio de chatarra.", "desc": "Mayor siderúrgica de EE.UU. por capacidad, pionera del modelo minimill (EAF + chatarra). Su división de productos de construcción (Vulcraft/Verco) ha citado la construcción de datacenters como driver de demanda en 2024-2025."},
  "ArcelorMittal": {"founded": 2006, "employees": 125, "revenue_2025": "~US$62.850M (TTM, verificado)", "market_cap": "~US$52.200M (verificado jul-2026)", "capacity": "~88 millones t/año nameplate crudo (producción real ~57-58 Mt/año por utilización)", "geo_risk": "Expuesta a precio de CO2/ETS europeo y a acero chino subsidiado; operación en EE.UU. protegida por arancel del 50%.", "desc": "Segunda mayor siderúrgica del mundo, formada en 2006 por fusión de Arcelor y Mittal Steel. Opera en Europa, América y Asia con integración parcial hacia minería de hierro propia."},
  "POSCO": {"founded": 1968, "employees": 42, "revenue_2025": "~US$45.680M (TTM, verificado)", "market_cap": "~US$16.100M (ADR, verificado jul-2026; nota: puede subestimar el valor total del grupo cotizado en KRX)", "capacity": "~38 millones t/año acero crudo (Pohang + Gwangyang)", "geo_risk": "Expuesta a aranceles Sección 232 de EE.UU. y a dumping de acero chino en mercado asiático.", "desc": "Mayor siderúrgica surcoreana, con dos complejos integrados (Pohang, Gwangyang). Su holding diversificó hacia materiales de baterías (litio, cátodos) como segundo pilar de crecimiento ante la madurez del negocio de acero."},
  "NipponSteel": {"founded": 1970, "employees": 113, "revenue_2025": "~US$68.000M (TTM, ¥10,06 billones, verificado)", "market_cap": "~US$19.000M (¥2,82 billones, verificado jul-2026)", "capacity": "~44 Mt/año doméstico Japón + ~22 Mt/año US Steel ≈ ~66 Mt/año combinado (aprox.)", "geo_risk": "Adquisición de US Steel (jun-2025, US$14.100M, US$55/acción) incluyó \"golden share\" para el gobierno de EE.UU. y compromisos de inversión sujetos a escrutinio CFIUS; Japón no produce mineral de hierro propio.", "desc": "Mayor siderúrgica de Japón. Completó la adquisición de United States Steel el 18 de junio de 2025 por US$14.100M (US$55/acción), tras litigar contra el bloqueo inicial del gobierno de Biden (enero 2025). El acuerdo final incluyó una \"golden share\" para EE.UU. con derecho de veto sobre ciertas decisiones."},
  "ChinaBaowu": {"founded": 2016, "capacity": "~130 millones t/año crudo (130,8 Mt en 2023 confirmado; mantiene liderazgo mundial en 2025)", "geo_risk": "Política china de \"supply-side reform\" busca consolidar/recortar capacidad; exportaciones enfrentan aranceles antidumping crecientes en UE, EE.UU., India, Brasil, México.", "desc": "Mayor grupo siderúrgico del mundo por volumen, formado en 2016 por fusión de Baosteel y WISCO bajo supervisión de SASAC. Su sobrecapacidad y exportaciones a precio bajo son el principal factor de distorsión de precios globales de acero."},
