  "AnhuiConch": {"founded": 1997, "employees": 48, "revenue_2025": "~US$11.470M (FY2025, CNY82.530M, verificado, -9,3% interanual)", "market_cap": "~US$12.570M (CNY90.440M, verificado jul-2026)", "capacity": "~270-330 millones t/año de capacidad de cemento y clinker (aprox.)", "geo_risk": ">90% de ingresos ligados al mercado doméstico chino, con exposición directa a la crisis del sector inmobiliario desde 2021; exceso de capacidad genera presión exportadora.", "desc": "Mayor productor de cemento por capacidad del mundo. La crisis del sector inmobiliario chino desde 2021 ha golpeado severamente su utilización de plantas y rentabilidad, con ingresos en caída sostenida."},
  "MesserGroup": {"founded": 1898, "geo_risk": "Opera en >35 países; expuesta a precio de energía europeo (Alemania) para separación de aire.", "desc": "Mayor empresa independiente de gases industriales del mundo, de propiedad familiar. Adquirió activos de Praxair y Linde divestidos por requerimiento antimonopolio tras la fusión Praxair-Linde de 2018, expandiendo su huella en Norteamérica y Sudamérica."},
  "NipponSanso": {"founded": 1910, "employees": 20, "revenue_2025": "~US$9.190M (TTM, verificado)", "market_cap": "~US$17.230M (¥2,55 billones, verificado jul-2026)", "geo_risk": "Fuerte exposición a Taiwán/Corea/Japón (concentración geográfica de fabs de clientes); expuesta a controles de exportación de gases raros (ej. neón, con Ucrania como fuente históricamente relevante para algunos gases).", "desc": "Cuarto mayor productor mundial de gases industriales, con fuerte presencia en gases especiales para semiconductores vía su filial estadounidense Matheson Tri-Gas. Compite directamente con Air Liquide, Linde y Air Products por contratos on-site en fabs de Asia."},
  "SKMaterials": {"founded": 1982, "geo_risk": "Corea del Sur; expuesta a controles de exportación china sobre materias primas de flúor usadas en gases especiales.", "desc": "Productor surcoreano de gases especiales (NF3, WF6) para semiconductores, integrado en el grupo SK desde 2015 (absorbido operativamente en SK Inc en 2022). Provee directamente a SK Hynix (mismo grupo corporativo) y a Samsung."},
  "AirWater": {"founded": 1929, "employees": 20, "revenue_2025": "~US$7.300M (FY2025, verificado)", "market_cap": "~US$4.070M (¥602.380M, verificado jul-2026)", "geo_risk": "Concentrada en Japón; expuesta a precio eléctrico japonés para separación de aire.", "desc": "Gasera industrial japonesa diversificada más allá de gases puros (incl. energía, agricultura, salud), lo que reduce su ciclicidad frente a competidores enfocados exclusivamente en semiconductores."},
